"""Fill measured report sections from completed, qualified data (offline only)."""
import collections,json,statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];DATA=ROOT/'docs/data/profiling'
def load(f):return json.loads((DATA/f).read_text())
def number(v,n=2):return f'{v:,.{n}f}'
def percent(v):return f'{v:+.2f}%'
def ci(v):return f"{percent(v['percent'])} [{percent(v['low'])}, {percent(v['high'])}]"
def table(headers,rows):return '| '+' | '.join(headers)+' |\n|'+'|'.join(' --- ' for _ in headers)+'|\n'+''.join('| '+' | '.join(str(x) for x in row)+' |\n' for row in rows)
def main():
    b,a,m=load('benchmarks.json'),load('analysis.json'),load('manifest.json');work=b['registration']['workloads'];groups={(g['workloadId'],g['buildId'],g['mode']):g for g in b['groups']};noise={(n['workload'],n['build']):n for n in a['unprofiledVariability']};cmp={c['workloadId']:c['currentVsPrevious'] for c in b['comparisons']};inc={(n['workload'],n['build'],n['period']):n for n in a['additionalStackInterference']}
    rows=[]
    for w in work:
        k=w['id'];old,now=groups[k,'before','plain'],groups[k,'after','plain'];rows.append([k,number(old['wall']['median'],4),number(now['wall']['median'],4),ci(cmp[k]),number(noise[k,'after']['coefficientOfVariationPercent'])+'%',number(now['nodesPerSecond']/1e6,2),number(now['evaluationsPerSecond']/1e6,2)])
    text=f"**Completed native matrix:** {a['trialCount']} full fixed-work trials, {a['captureCount']} profiler captures. Cells below are elapsed change with a descriptive 95% paired interval; negative means less elapsed time. Both complete old/current trial matrices remain in the JSON.\n\n"
    text+=table(['Workload','Previous median s','Current median s','Current vs previous','Current plain CV','Current M nodes/s','Current M eval/s'],rows)
    text+='\nCurrent-engine application interference:\n\n'
    for modes in [['ip-1000000','ip-10000000','stacks-1000000','stacks-10000000'],['cpu-normal','cpu-high','time-normal','time-high']]:
        text+=table(['Workload',*modes],[[w['id'],*[ci(groups[w['id'],'after',mode]['wallEffect']) for mode in modes]] for w in work])+'\n'
    text+='Additional interference from requesting user stacks, with the minimal collectors otherwise matched:\n\n'+table(['Workload','1 M cycles: elapsed','1 M cycles: thread CPU','10 M cycles: elapsed','10 M cycles: thread CPU'],[[w['id'],ci(inc[w['id'],'after',1000000]['wall']),ci(inc[w['id'],'after',1000000]['cpu']),ci(inc[w['id'],'after',10000000]['wall']),ci(inc[w['id'],'after',10000000]['cpu'])] for w in work])
    text+='\nDensity/volume example, current static B (five captures per condition):\n\n'+table(['Mode','Median samples','Median accepted samples/s','Median raw MiB','Exported median weight'],[[mode,number(groups['evaluate-B','after',mode]['sampleCount']['median'],0),number(groups['evaluate-B','after',mode]['sampleCount']['median']/groups['evaluate-B','after',mode]['wall']['median'],0),number(groups['evaluate-B','after',mode]['traceBytes']['median']/2**20),number(statistics.median(c['weightStatistics']['median'] for c in b['captureStatistics'] if (c['workloadId'],c['buildId'],c['mode'])==('evaluate-B','after',mode)),0)] for mode in b['registration']['modes'] if mode!='plain'])
    text+='\nWeights in that last column are configured cycle periods for minimal PMIs, exported cycles for CPU Profiler, and nominal nanoseconds for Time Profiler. They are not a common elapsed-time scale.\n\n'
    text+='Physical-function distribution agreement, pooled over five captures per method (total variation is half the absolute share differences, in percentage points):\n\n'+table(['Workload','IP vs raw cycle stacks','IP vs CPU Profiler','IP vs Time Profiler'],[[w['id'],*[number(next(x['totalVariationPercent'] for x in a['hotspotComparisons'] if (x['workload'],x['build'],x['b'])==(w['id'],'after',mode)))+' pp' for mode in ['stacks-1000000','cpu-normal','time-normal']]] for w in work])
    text+='\nFine instruction/64-byte region comparisons, every function share, depth/core distribution and accepted/discarded/unresolved counts are in [the analysis](data/profiling/analysis.json) and capture statistics. Fine address rankings have substantially less count support than whole-function rankings; disagreement at that level can reflect sparse observations, skid, period/phase effects and representation differences.\n'
    evaltext=''
    for wid in ['evaluate-B','evaluate-P']:
        g=groups[wid,'after','plain'];p=next(x for x in a['hotspotComparisons'] if (x['workload'],x['build'],x['b'])==(wid,'after','stacks-1000000'));top=list(p['sharesA'].items())[:3]
        evaltext+=f"For **{wid}**, the unprofiled body-only rate is **{number(g['evaluationsPerSecond']/1e6)} million evaluations/s**, plain CV {number(noise[wid,'after']['coefficientOfVariationPercent'])}%. At 1 M cycles, IP elapsed change is {ci(groups[wid,'after','ip-1000000']['wallEffect'])}; raw stacks versus plain is {ci(groups[wid,'after','stacks-1000000']['wallEffect'])}. The incremental stack request is {ci(inc[wid,'after',1000000]['wall'])}. Leading physical IP symbols are "+'; '.join(f'`{name}` ({100*share:.2f}%)' for name,share in top)+f". IP/stack function-distribution variation is {p['totalVariationPercent']:.2f} pp.\n\n"
    evaltext+='These rates include the external call/loop/checksum and exclude recomputing own legal moves, so they must not be substituted for the older full-static benchmark rates. No invocation count is inferred from a sampled frame. The committed standard CPU/Time profiles show whatever inline expansion their actual exports supplied; raw PMI stacks add none.\n'
    exact=groups['exact-P','after','plain'];old=groups['exact-P','before','plain'];paths={k:v for k,v in a['finalEmptyCallerEvidence'].items() if 'after-cpu-normal-0' in k};path=next(iter(paths.values()))
    exacttext=f"On this **one disclosed twelve-empty root**, complete fixed work falls from **{old['wall']['median']:.4f} s to {exact['wall']['median']:.4f} s**; current/previous paired change is {ci(cmp['exact-P'])}. This is a narrower root-specific result than the earlier independent twelve-root batch. The CPU Profiler capture places the helper in {path['helperInclusivePercent']:.2f}% of accepted inclusive cycle-period weight; {path['withMainPercent']:.2f}% of its weight retains a `main` frame.\n\nActual observed helper caller paths include:\n\n"+'\n'.join('- `'+k+'`.' for k in list(path['actualCallerPaths'])[:3])+'\n\nThe differential table explains redistribution, the real icicle establishes calling context, and the unprofiled benchmark establishes the practical benefit. A larger helper share is not a regression.\n'
    shares={}
    for tag in ['before','after']:
        profile=load('exact-P-'+tag+'-ip-1000000-0.json');weights=collections.Counter()
        for sample in profile['samples']:
            frame=profile['frames'][sample[1]];weights[frame.get('containingSymbol',frame['name'])]+=sample[2]
        shares[tag]={name:100*weight/profile['accounting']['weight'] for name,weight in weights.items()}
    exacttext+='\nSelected complete rep-0 IP captures (independent all-accepted denominators, same event/period):\n\n'
    exacttext+=table(['Physical function','Previous cycle-sample share','Current cycle-sample share'],[[name,*[number(sum(v for k,v in shares[tag].items() if token in k))+'%' for tag in ['before','after']]] for name,token in [('negamax','Engine::negamax('),('flips','reversi::flips('),('legal','reversi::legal('),('lastEmpties','Engine::lastEmpties(')]])
    exacttext+='\n`flips` gains share while the complete search becomes faster. General recursion/legal-work share falls and the specialized helper appears. This supports redistribution, not a precise absolute time saving for any instruction. Build-specific instruction addresses and source/assembly remain inspectable in the IP table and address zoom; they are not aligned solely by equal numeric offsets.\n'
    ips=[groups[w['id'],'after',mode]['wallEffect'] for w in work for mode in ['ip-1000000','ip-10000000']];stacks=[inc[w['id'],'after',period]['wall'] for w in work for period in [1000000,10000000]]
    agreement=[x for x in a['hotspotComparisons'] if x['build']=='after' and x['b']=='stacks-1000000'];sameLeader=sum(x['top5A'][0]==x['top5B'][0] for x in agreement)
    evalEffects=[groups[w,'after',mode]['wallEffect'] for w in ['evaluate-B','evaluate-P'] for mode in ['ip-1000000','cpu-high']]
    density=groups['evaluate-B','after','ip-1000000']['sampleCount']['median']/groups['evaluate-B','after','ip-10000000']['sampleCount']['median']
    recommendations='''Regular use should center on three views: **(1) repeated unprofiled benchmark/interference plots, (2) flat hardware-IP tables with source/assembly and optional address sunburst zoom, and (3) an on-demand genuine-stack icicle/Speedscope view**. The sunburst is particularly useful for a broad physical function with a compact hot region; a table remains more precise for ranking. The chronological sample chart adds less to these steady single-thread loops, but is useful for phase/core movement and worker/idle context.\n\nStart a future pilot with 10 M cycle IP sampling for coarse function questions, then use 1 M when finer instruction support is needed. Recheck target interference and sample coverage for that workload. Collect stacks when caller information can resolve a question; do not reject them on an assumption that unwinding must be expensive. The measured intervals and data costs, rather than a zero-overhead claim, should decide the period.\n\n'''
    recommendations+=table(['Question','Answer'],[
      ['1. Genuine M4 hardware IP-only samples?','**Yes.** Explicit counter configuration plus PMI records with empty user/kernel stack requirements and fields; selected exports are checked for hidden stack tables.'],
      ['2. Actual hardware events?','Accepted minimal captures use **CORE_ACTIVE_CYCLE**, event 17 in this CPU-family database, at 1 M / 10 M periods. CPU Profiler’s exported collector requirements also identify CORE_ACTIVE_CYCLE at 1 M / 100 k cycles; its individual cycle weights are retained. Periodic/V8 profiles are separate software samples; recovered branch-related probes are not primary cycle evidence.'],
      ['3. Measurable IP interference?',f"Current-engine point estimates span {min(x['percent'] for x in ips):+.2f}% to {max(x['percent'] for x in ips):+.2f}%; {sum(x['low']>0 for x in ips)} of 12 mode/workload intervals lie wholly above zero. Other small differences remain unresolved at this precision; this does not prove zero overhead."],
      ['4. Additional stack interference?',f"Matched raw-stack versus IP elapsed estimates span {min(x['percent'] for x in stacks):+.2f}% to {max(x['percent'] for x in stacks):+.2f}%; {sum(x['low']>0 for x in stacks)} of 12 intervals lie wholly above zero. See per-period CPU/elapsed intervals and collector costs; do not substitute differences between shipped templates for a pure unwinding cost."],
      ['5. Tiny evaluator performance?',f"Static B at 1 M-cycle IP shows {ci(groups['evaluate-B','after','ip-1000000']['wallEffect'])}; static P shows {ci(groups['evaluate-P','after','ip-1000000']['wallEffect'])}. Dense CPU Profiler shows {ci(groups['evaluate-B','after','cpu-high']['wallEffect'])} B and {ci(groups['evaluate-P','after','cpu-high']['wallEffect'])} P. B has a resolved condition-associated increase; P's IP result is unresolved. No per-call instrumentation was added."],
      ['6. Frequency dependence?',f"The static B 1 M-cycle IP capture density is {density:.2f}× the 10 M setting. CPU Profiler high is about 10× normal density; Time Profiler uses 1,000/100 µs. Dense CPU Profiler consistently adds a clearer elapsed penalty; raw IP frequency effects are smaller and are not uniformly resolved. The tables/plots retain actual counts, volume, weights and uncertainty."],
      ['7. Same important hotspots?',f"IP and matched raw stacks have the same leading physical symbol in {sameLeader}/6 current workloads; pooled function-distribution variation spans {min(x['totalVariationPercent'] for x in agreement):.2f}–{max(x['totalVariationPercent'] for x in agreement):.2f} pp. Individual instructions/regions are less stable; sparse counts, skid, aliasing, inlining and core weighting remain limits."],
      ['8. Best instruction-cost views?','Sortable IP/function tables with actual assembly/source, followed by address-containment sunburst refinement. No caller inference is made from these rings.'],
      ['9. Best calling-context views?','A real sampled-stack icicle/flame graph, supported by self/inclusive tables and weighted Speedscope export.'],
      ['10. Best final-empty explanation?','Function/path differential plus genuine helper caller paths explain redistribution; unprofiled full-search elapsed time establishes benefit.'],
      ['11. What would Processor Trace add?','Control-flow/branch sequences and short-call behavior between samples, with much larger data/decoding cost. Hardware support exists, but this Mac is not enabled; no setting was changed and no Reversi trace-overhead claim is made.'],
      ['12. Future combination?','Fixed-work unprofiled controls + qualified hardware IP tables/refinement + selective real stacks. Use chronology when timing/context is the question, and bounded trace only for a question sampling cannot resolve.']])
    sections={'MEASURED_RESULTS':text,'EVALUATOR_EXAMPLE':evaltext,'FINAL_EMPTY_EXAMPLE':exacttext,'RECOMMENDATIONS_AND_ANSWERS':recommendations}
    path=ROOT/'docs/PROFILING_METHODS_AND_VIEWS.md';document=path.read_text()
    for marker,value in sections.items():
        start=f'<!-- {marker} -->';end=f'<!-- END_{marker} -->'
        if end in document:
            i=document.index(start)+len(start);j=document.index(end);document=document[:i]+'\n\n'+value+'\n'+document[j:]
        else:document=document.replace(start,start+'\n\n'+value+'\n'+end)
    path.write_text(document)
if __name__=='__main__':main()
